fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut on: i32 = host::display::state_get(1);
    if down == 1 && prev == 0 {
        on = 1 - on;
        if on == 0 { host::audio::stop(-1); }
    }
    host::display::state_set(0, down);
    host::display::state_set(1, on);
    let hi: i32 = (t / 30) % 2;
    if on == 1 && t % 30 == 0 {
        if hi == 1 {
            host::audio::tone(900, 290, 2);
        } else {
            host::audio::tone(600, 290, 2);
        }
    }
    let mut left: i32 = 0x200008;
    let mut right: i32 = 0x000820;
    if on == 1 && hi == 1 { left = 0xff2020; }
    if on == 1 && hi == 0 { right = 0x4060ff; }
    host::display::clear(0x000000);
    host::display::fill_rect(0, 0, w / 2, h, left);
    host::display::fill_rect(w / 2, 0, w / 2, h, right);
    if on == 1 {
        host::display::draw_string(24, h / 2, "TAP = OFF", 0xffffff, 2);
    } else {
        host::display::draw_string(24, h / 2, "TAP = SIREN", 0xffffff, 2);
    }
    host::display::present();
}
